var e=JSON.parse(`[{"id":"fr2-entrecote-bordelaise","name":"Entrecôte à la bordelaise, moelle et grenailles rôties","description":"Une belle entrecôte saisie, nappée d'une sauce au vin rouge et aux échalotes enrichie de moelle pochée. Grenailles dorées à la graisse de canard.","emoji":"🥩","category":"plat","mealTypes":["diner","dejeuner"],"cuisine":"francaise","prepTime":15,"cookTime":40,"difficulty":"facile","servings":2,"ingredients":[{"id":"boeuf-entrecote","qty":350,"unit":"g","note":"1 belle entrecôte de 3 cm d'épaisseur"},{"id":"os-a-moelle","qty":1,"unit":"piece","note":"tronçon de 8 cm"},{"id":"echalote","qty":3,"unit":"piece","note":"ciselées finement"},{"id":"vin-rouge","qty":200,"unit":"ml","note":"un bordeaux"},{"id":"bouillon-boeuf","qty":100,"unit":"ml"},{"id":"beurre","qty":20,"unit":"g","note":"froid, en dés"},{"id":"pomme-de-terre","qty":500,"unit":"g","note":"grenailles"},{"id":"graisse-canard","qty":2,"unit":"cac"},{"id":"thym","qty":2,"unit":"brin"},{"id":"persil","qty":5,"unit":"g","note":"ciselé"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 200 °C. Coupez les grenailles en deux, enrobez-les de graisse de canard, de thym et de sel, et rôtissez-les 35 min sur une plaque en les retournant à mi-cuisson : elles doivent être dorées et croustillantes.","Faites tremper l'os à moelle 10 min dans l'eau froide salée, puis pochez-le 8 min dans une petite casserole d'eau frémissante. Poussez la moelle hors de l'os avec le manche d'une cuillère et coupez-la en rondelles.","Sortez l'entrecôte du réfrigérateur 30 min avant. Faites chauffer une poêle en fonte à feu vif avec 5 g de beurre jusqu'à ce qu'il mousse et commence à blondir.","Saisissez l'entrecôte 3 à 4 min par face pour une cuisson saignante (5 min pour à point), en arrosant de beurre moussant. Réservez-la sur une planche sous une feuille de papier aluminium 5 min.","Dans la même poêle à feu moyen, faites suer les échalotes 2 min dans le gras de cuisson. Versez le vin rouge et faites réduire de trois quarts (environ 6 min), puis ajoutez le bouillon et réduisez encore 3 min jusqu'à consistance sirupeuse.","Hors du feu, incorporez le reste du beurre froid en fouettant, puis les rondelles de moelle. Poivrez généreusement.","Tranchez l'entrecôte, nappez de sauce, parsemez de persil et servez avec les grenailles."],"tags":["week-end","riche en protéines","calorique","four","prise de masse"],"seasons":["automne","hiver"],"technique":"poele","flavors":["umami","grille"],"tips":"La moelle peut être remplacée par une noix de beurre supplémentaire. Demandez au boucher de scier les os."},{"id":"fr2-tartare-boeuf-frites-four","name":"Tartare de bœuf au couteau, frites au four","description":"Le tartare de brasserie, coupé au couteau, relevé de câpres, cornichons et échalote, avec de vraies frites dorées au four à la graisse de canard et une salade verte.","emoji":"🥩","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":35,"difficulty":"facile","servings":2,"ingredients":[{"id":"boeuf-steak","qty":400,"unit":"g","note":"rumsteck ou filet extra-frais"},{"id":"jaune-oeuf","qty":2,"unit":"piece","note":"œufs très frais"},{"id":"echalote","qty":1,"unit":"piece","note":"ciselée très finement"},{"id":"capres","qty":1,"unit":"cas","note":"hachées"},{"id":"cornichon","qty":30,"unit":"g","note":"hachés"},{"id":"moutarde","qty":2,"unit":"cac"},{"id":"persil","qty":10,"unit":"g","note":"ciselé"},{"id":"huile-olive","qty":2,"unit":"cas"},{"id":"piment-espelette","qty":1,"unit":"pincee"},{"id":"pomme-de-terre-farineuse","qty":700,"unit":"g","note":"bintje"},{"id":"graisse-canard","qty":2,"unit":"cas","note":"fondue"},{"id":"laitue","qty":100,"unit":"g"},{"id":"vinaigre-cidre","qty":1,"unit":"cas","note":"vinaigre de vin"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 220 °C (chaleur tournante). Taillez les pommes de terre en frites de 1 cm, rincez-les à l'eau froide et séchez-les soigneusement dans un torchon.","Enrobez les frites de graisse de canard fondue, étalez-les en une seule couche sur une plaque recouverte de papier cuisson et enfournez 35 min en les retournant à mi-cuisson : elles doivent être dorées et croustillantes sur les bords. Salez à la sortie.","Pendant ce temps, placez la viande 10 min au congélateur pour la raffermir, puis coupez-la au couteau en petits dés de 3 à 4 mm. Gardez-la au frais.","Dans un saladier froid, mélangez la moutarde, 1 cuillère d'huile, les câpres, les cornichons, l'échalote, le persil, le piment, du sel et du poivre.","Ajoutez la viande au dernier moment et mélangez à la fourchette sans écraser. Dressez en deux dômes à l'aide d'un cercle et creusez légèrement le sommet pour y déposer un jaune d'œuf.","Assaisonnez la salade avec le vinaigre et le reste d'huile. Servez immédiatement le tartare bien froid avec les frites brûlantes et la salade."],"tags":["riche en protéines","sportif","four","prise de masse","familial"],"seasons":["printemps","ete"],"technique":"cru","flavors":["acidule","frais","umami"],"tips":"N'achetez la viande que le jour même et ne la préparez qu'au dernier moment. Ne pas préparer à l'avance."},{"id":"fr2-boeuf-carottes-pied-veau","name":"Bœuf aux carottes à l'ancienne, purée au beurre","description":"Le bœuf mode de grand-mère : gîte et pied de veau mijotés au vin blanc avec beaucoup de carottes fondantes, dans une sauce naturellement gélifiée. Servi sur une purée maison.","emoji":"🥕","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":210,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"boeuf-jarret","qty":1000,"unit":"g","note":"gîte ou jarret, en gros morceaux"},{"id":"pied-veau","qty":300,"unit":"g","note":"fendu en deux par le boucher"},{"id":"carotte","qty":8,"unit":"piece","note":"en rondelles épaisses"},{"id":"oignon","qty":2,"unit":"piece","note":"émincés"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"vin-blanc","qty":300,"unit":"ml"},{"id":"bouillon-boeuf","qty":400,"unit":"ml"},{"id":"beurre","qty":55,"unit":"g"},{"id":"pomme-de-terre-farineuse","qty":900,"unit":"g"},{"id":"lait","qty":150,"unit":"ml","note":"chaud"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"thym","qty":3,"unit":"brin"},{"id":"muscade","qty":1,"unit":"pincee"},{"id":"persil","qty":10,"unit":"g","optional":true},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Blanchissez le pied de veau : plongez-le 5 min dans l'eau bouillante, égouttez et rincez à l'eau froide.","Dans une cocotte en fonte, faites chauffer 20 g de beurre à feu vif et colorez les morceaux de bœuf 3 min par face, en deux fournées, jusqu'à ce qu'ils soient bien bruns. Réservez.","À feu moyen, faites fondre les oignons 5 min dans la cocotte. Remettez la viande, ajoutez le pied de veau, l'ail écrasé, le thym et le laurier.","Versez le vin blanc, laissez bouillir 2 min, puis ajoutez le bouillon. Couvrez et laissez mijoter 2 h à tout petit frémissement (ou au four à 150 °C).","Ajoutez les carottes, salez, poivrez et poursuivez 1 h 15 à couvert : la viande doit se défaire à la cuillère et les carottes être fondantes. Retirez le pied de veau, détachez-en la chair gélatineuse et remettez-la dans la sauce.","Pendant la dernière demi-heure, cuisez les pommes de terre épluchées 25 min dans l'eau salée, écrasez-les au presse-purée avec 35 g de beurre, le lait chaud et la muscade.","Rectifiez l'assaisonnement de la sauce (réduisez-la 5 min à découvert si elle est trop liquide), parsemez de persil et servez sur la purée."],"tags":["mijoté","week-end","batch cooking","riche en collagène","réconfortant","familial"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["reconfortant","umami"],"tips":"Encore meilleur réchauffé le lendemain. Froid, le jus prend en gelée : on peut le servir en bœuf mode en gelée l'été."},{"id":"fr2-rognons-veau-madere-riz","name":"Rognons de veau au madère et aux champignons, riz pilaf","description":"Rognons de veau saisis rosés à feu vif, sauce brune au madère et champignons de Paris, liée d'un trait de crème. Riz pilaf pour la sauce.","emoji":"🍄","category":"plat","mealTypes":["diner","dejeuner"],"cuisine":"francaise","prepTime":15,"cookTime":30,"difficulty":"facile","servings":2,"ingredients":[{"id":"rognon","qty":450,"unit":"g","note":"rognon de veau dégraissé"},{"id":"champignon","qty":250,"unit":"g","note":"en lamelles"},{"id":"echalote","qty":2,"unit":"piece","note":"ciselées"},{"id":"vin-rouge","qty":100,"unit":"ml","note":"madère ou porto"},{"id":"bouillon-boeuf","qty":400,"unit":"ml","note":"dont 300 ml pour le riz"},{"id":"creme-fraiche","qty":50,"unit":"ml"},{"id":"beurre","qty":40,"unit":"g"},{"id":"riz-blanc","qty":160,"unit":"g"},{"id":"oignon","qty":0.5,"unit":"piece","note":"pour le pilaf"},{"id":"persil","qty":5,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Riz pilaf : faites suer l'oignon haché 2 min dans 10 g de beurre, ajoutez le riz et remuez 1 min jusqu'à ce qu'il soit nacré. Versez 300 ml de bouillon bouillant, couvrez et cuisez 17 min à feu très doux.","Retirez la membrane et les nerfs blancs des rognons, coupez-les en morceaux de 2 cm.","Faites chauffer une poêle à feu très vif sans matière grasse, jetez-y les rognons 1 min pour qu'ils rendent leur eau, puis égouttez-les dans une passoire et jetez le jus (c'est ce qui enlève l'amertume).","Remettez la poêle à feu vif avec 15 g de beurre et saisissez les rognons 2 min en remuant : ils doivent être dorés dehors et rosés dedans. Réservez.","Dans la même poêle à feu moyen, faites revenir les échalotes et les champignons dans 10 g de beurre 5 min. Déglacez au madère, réduisez de moitié (2 min), ajoutez 100 ml de bouillon et réduisez encore 3 min.","Ajoutez la crème, laissez bouillonner 1 min, remettez les rognons 1 min juste pour les réchauffer sans les recuire. Ajoutez le reste du beurre, poivrez, parsemez de persil et servez avec le riz."],"tags":["abats","rapide","riche en protéines","une poêle"],"seasons":[],"technique":"poele","flavors":["umami","cremeux"]},{"id":"fr2-miroton-boeuf","name":"Bœuf miroton gratiné aux oignons","description":"Le plat bourgeois parisien : tranches de bœuf bouilli mijotées dans une sauce aux oignons relevée de vinaigre et de tomate, gratinées à la chapelure. Pommes vapeur pour saucer.","emoji":"🧅","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":170,"difficulty":"facile","servings":4,"ingredients":[{"id":"boeuf-paleron","qty":900,"unit":"g","note":"ou un reste de pot-au-feu"},{"id":"oignon","qty":4,"unit":"piece","note":"émincés finement"},{"id":"bouillon-boeuf","qty":1200,"unit":"ml","note":"dont 300 ml pour la sauce"},{"id":"vin-blanc","qty":150,"unit":"ml"},{"id":"vinaigre-cidre","qty":2,"unit":"cas","note":"vinaigre de vin"},{"id":"concentre-tomate","qty":1,"unit":"cas"},{"id":"farine","qty":1,"unit":"cas"},{"id":"beurre","qty":50,"unit":"g"},{"id":"panure","qty":30,"unit":"g"},{"id":"pomme-de-terre","qty":1000,"unit":"g"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"thym","qty":2,"unit":"brin"},{"id":"persil","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Placez le paleron dans une cocotte avec 900 ml de bouillon, le laurier et le thym, complétez d'eau à hauteur. Portez à frémissement, écumez et laissez cuire 2 h 15 à couvert, à petits bouillons : la viande doit être tendre à la pointe du couteau. (Sautez cette étape avec un reste de pot-au-feu.)","Laissez tiédir la viande puis coupez-la en tranches de 1 cm contre le sens des fibres.","Dans une sauteuse, faites fondre les oignons dans 35 g de beurre à feu moyen-doux 15 min, jusqu'à ce qu'ils soient dorés. Saupoudrez de farine et remuez 1 min.","Ajoutez le concentré de tomate, le vin blanc et 300 ml de bouillon de cuisson. Laissez épaissir 10 min à feu doux, puis ajoutez le vinaigre, salez et poivrez généreusement.","Préchauffez le four à 200 °C. Dans un plat beurré, alternez sauce et tranches de bœuf, terminez par la sauce. Parsemez de chapelure et du reste de beurre en noisettes.","Enfournez 25 min jusqu'à ce que le dessus soit gratiné et que la sauce bouillonne sur les bords. Pendant ce temps, cuisez les pommes de terre épluchées 25 min à la vapeur.","Parsemez de persil et servez bien chaud avec les pommes vapeur."],"tags":["week-end","économique","four","réconfortant","préparation à l’avance","familial"],"seasons":["automne","hiver"],"technique":"four","flavors":["acidule","reconfortant","umami"],"tips":"Le miroton est né pour accommoder les restes de bœuf bouilli : idéal le surlendemain d'un pot-au-feu."},{"id":"fr2-roti-boeuf-gratin-dauphinois","name":"Rôti de bœuf du dimanche, gratin dauphinois","description":"Un rôti de bœuf saisi au beurre et rôti rosé, tranché finement avec son jus, accompagné d'un vrai gratin dauphinois au lait, à la crème et à l'ail.","emoji":"🥩","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":90,"restTime":10,"difficulty":"facile","servings":4,"ingredients":[{"id":"boeuf-rosbif","qty":900,"unit":"g","note":"rôti ficelé, finement bardé"},{"id":"pomme-de-terre","qty":1000,"unit":"g","note":"à chair ferme, en rondelles de 3 mm, non lavées"},{"id":"lait","qty":400,"unit":"ml"},{"id":"creme-liquide","qty":200,"unit":"ml"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"muscade","qty":1,"unit":"pincee"},{"id":"beurre","qty":40,"unit":"g"},{"id":"echalote","qty":1,"unit":"piece"},{"id":"thym","qty":3,"unit":"brin"},{"id":"moutarde","qty":1,"unit":"cas","note":"pour servir"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Sortez le rôti 1 h avant. Préchauffez le four à 160 °C.","Gratin : dans une casserole, portez le lait, la crème, 2 gousses d'ail écrasées, la muscade, 1 cuillère à café de sel et du poivre à frémissement. Ajoutez les rondelles de pommes de terre et laissez frémir 10 min en remuant délicatement : l'amidon épaissit le liquide.","Frottez un plat à gratin avec la dernière gousse d'ail et 10 g de beurre. Versez-y les pommes de terre et leur crème, lissez et enfournez 1 h 15, jusqu'à ce que le dessus soit doré et que la pointe d'un couteau traverse sans résistance.","40 min avant la fin du gratin, salez le rôti et saisissez-le dans une cocotte avec 20 g de beurre à feu vif, 2 min sur chaque face, jusqu'à ce qu'il soit bien coloré. Ajoutez l'échalote coupée en deux et le thym.","Montez le four à 200 °C (le gratin finit de dorer) et enfournez le rôti dans sa cocotte 25 à 30 min (cœur à 52 °C pour rosé, 58 °C pour à point).","Laissez reposer le rôti 10 min sous aluminium. Déglacez la cocotte avec 4 cuillères d'eau et le reste du beurre en grattant les sucs pour faire un jus.","Tranchez finement, arrosez de jus et servez avec le gratin et la moutarde."],"tags":["week-end","familial","four","riche en protéines","calorique"],"seasons":[],"technique":"roti","flavors":["umami","cremeux"],"tips":"Les restes de rôti froid font d'excellents sandwichs au pain de campagne avec cornichons et moutarde."},{"id":"fr2-roti-dinde-marrons","name":"Rôti de dinde aux marrons et aux pommes","description":"Le rôti des fêtes de grand-mère, tous les jours : filet de dinde bardé de lard, rôti en cocotte au vin blanc avec marrons glacés au jus, pommes fruits et petits oignons.","emoji":"🌰","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":70,"restTime":10,"difficulty":"facile","servings":4,"ingredients":[{"id":"dinde-escalope","qty":1000,"unit":"g","note":"rôti de dinde (filet) ficelé"},{"id":"bacon","qty":8,"unit":"piece","note":"fines tranches pour barder"},{"id":"chataigne","qty":500,"unit":"g","note":"marrons cuits sous vide"},{"id":"pomme","qty":2,"unit":"piece","note":"en quartiers"},{"id":"oignon-nouveau","qty":8,"unit":"piece","note":"ou petits oignons grelots"},{"id":"vin-blanc","qty":150,"unit":"ml"},{"id":"bouillon-volaille","qty":250,"unit":"ml"},{"id":"beurre","qty":50,"unit":"g"},{"id":"creme-fraiche","qty":60,"unit":"ml"},{"id":"thym","qty":3,"unit":"brin"},{"id":"sauge","qty":4,"unit":"feuille"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Salez et poivrez le rôti, enveloppez-le des tranches de bacon et glissez les feuilles de sauge dessous ; maintenez avec de la ficelle.","Dans une cocotte, faites mousser 25 g de beurre à feu moyen-vif et dorez le rôti 8 min sur toutes les faces, jusqu'à ce que le lard soit croustillant.","Ajoutez les petits oignons et le thym, versez le vin blanc et 150 ml de bouillon. Couvrez et laissez cuire 45 min à feu doux (ou au four à 170 °C), en retournant le rôti à mi-cuisson ; le cœur doit atteindre 70 °C.","Pendant ce temps, faites dorer les quartiers de pomme 6 min dans 15 g de beurre. Ajoutez les marrons, le reste du bouillon et du beurre, et laissez-les glacer 10 min à feu moyen en les roulant délicatement, jusqu'à ce qu'ils soient brillants.","Sortez le rôti et laissez-le reposer 10 min sous aluminium. Faites réduire le jus de la cocotte 3 min à feu vif, ajoutez la crème et laissez bouillonner 1 min.","Tranchez le rôti, nappez de sauce et servez avec les marrons, les pommes et les petits oignons."],"tags":["week-end","familial","riche en protéines","réconfortant"],"seasons":["automne","hiver"],"technique":"roti","flavors":["reconfortant","fruite"]},{"id":"fr2-veau-marengo","name":"Veau Marengo et tagliatelles fraîches","description":"Sauté de veau mijoté à l'huile d'olive, tomate, vin blanc et champignons, avec une pointe de zeste d'orange comme autrefois. Servi sur des tagliatelles fraîches au beurre.","emoji":"🍲","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":105,"difficulty":"facile","servings":4,"ingredients":[{"id":"veau-epaule","qty":1000,"unit":"g","note":"en cubes de 4 cm"},{"id":"tomates-concassees","qty":400,"unit":"g"},{"id":"concentre-tomate","qty":1,"unit":"cas"},{"id":"champignon","qty":300,"unit":"g","note":"en quartiers"},{"id":"oignon","qty":2,"unit":"piece","note":"hachés"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"vin-blanc","qty":250,"unit":"ml"},{"id":"bouillon-volaille","qty":200,"unit":"ml"},{"id":"huile-olive","qty":3,"unit":"cas"},{"id":"farine","qty":1,"unit":"cas"},{"id":"orange","qty":1,"unit":"piece","note":"zeste seulement","optional":true},{"id":"pates-fraiches","qty":500,"unit":"g","note":"tagliatelles"},{"id":"beurre","qty":20,"unit":"g"},{"id":"thym","qty":2,"unit":"brin"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"persil","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Épongez la viande. Dans une cocotte, faites chauffer 2 cuillères d'huile à feu vif et dorez le veau en deux fournées, 5 min chacune, jusqu'à ce qu'il soit doré. Réservez.","À feu moyen, faites fondre les oignons 4 min, ajoutez l'ail écrasé puis la viande. Saupoudrez de farine et remuez 1 min.","Versez le vin blanc, grattez les sucs, laissez réduire 3 min. Ajoutez tomates, concentré, bouillon, thym, laurier et un ruban de zeste d'orange. Salez, poivrez.","Couvrez et laissez mijoter 1 h 15 à feu doux : la viande doit être tendre à la fourchette.","Faites sauter les champignons dans le reste d'huile 5 min à feu vif, puis ajoutez-les à la cocotte pour 15 min de cuisson à découvert ; la sauce doit être nappante.","Cuisez les tagliatelles 3 min dans une grande casserole d'eau bouillante salée, égouttez et enrobez-les de beurre.","Retirez le zeste et le laurier, parsemez de persil et servez sur les tagliatelles."],"tags":["mijoté","week-end","batch cooking","familial","riche en protéines"],"seasons":["printemps","automne"],"technique":"mijote","flavors":["umami","herbace"],"tips":"Se congèle très bien sans les pâtes."},{"id":"fr2-saute-veau-olives-carottes","name":"Sauté de veau aux olives vertes et carottes, riz pilaf","description":"Un sauté de veau provençal, mijoté au vin blanc et aux herbes avec des olives vertes et des carottes confites. Riz pilaf au beurre.","emoji":"🫒","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":90,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"veau-epaule","qty":900,"unit":"g","note":"tendron ou épaule, en morceaux"},{"id":"olive","qty":150,"unit":"g","note":"vertes dénoyautées, rincées"},{"id":"carotte","qty":4,"unit":"piece","note":"en biseaux"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"vin-blanc","qty":250,"unit":"ml"},{"id":"bouillon-volaille","qty":750,"unit":"ml","note":"dont 500 ml pour le riz"},{"id":"huile-olive","qty":3,"unit":"cas"},{"id":"origan","qty":1,"unit":"cac","note":"herbes de Provence"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"riz-blanc","qty":300,"unit":"g","note":"riz long"},{"id":"beurre","qty":30,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites chauffer 2 cuillères d'huile d'olive dans une cocotte à feu vif et dorez le veau 6 à 8 min en deux fois. Salez peu (les olives sont salées), poivrez.","Ajoutez l'oignon émincé et l'ail écrasé, faites suer 3 min à feu moyen. Versez le vin blanc et laissez réduire de moitié (3 min).","Ajoutez 250 ml de bouillon, les carottes, les herbes de Provence et le laurier. Couvrez et laissez mijoter 1 h à feu doux.","Ajoutez les olives et poursuivez 20 min à découvert, jusqu'à ce que la sauce soit réduite et brillante.","Pour le riz pilaf : faites nacrer le riz 2 min dans 20 g de beurre et le reste d'huile, versez 500 ml de bouillon bouillant, couvrez et cuisez 17 min à feu très doux sans remuer. Laissez reposer 5 min, égrenez à la fourchette avec le reste du beurre.","Servez le sauté bien chaud avec le riz."],"tags":["mijoté","batch cooking","familial","préparation à l’avance","riche en protéines"],"seasons":["printemps","ete"],"technique":"mijote","flavors":["herbace","umami"]},{"id":"fr2-roti-veau-petits-pois-francaise","name":"Rôti de veau, petits pois à la française et grenailles","description":"Un rôti de veau doré au beurre, cuit en cocotte, servi avec des petits pois braisés à la laitue, aux lardons et aux petits oignons, et des grenailles fondantes.","emoji":"🫛","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":75,"restTime":10,"difficulty":"facile","servings":4,"ingredients":[{"id":"veau-epaule","qty":1000,"unit":"g","note":"rôti de noix ou d'épaule ficelé"},{"id":"petits-pois","qty":500,"unit":"g","note":"écossés ou surgelés"},{"id":"laitue","qty":175,"unit":"g","note":"½ laitue, en lanières"},{"id":"oignon-nouveau","qty":8,"unit":"piece"},{"id":"lardons","qty":100,"unit":"g"},{"id":"carotte","qty":2,"unit":"piece","note":"en rondelles"},{"id":"pomme-de-terre","qty":800,"unit":"g","note":"grenailles"},{"id":"beurre","qty":60,"unit":"g"},{"id":"bouillon-volaille","qty":250,"unit":"ml"},{"id":"ail","qty":3,"unit":"gousse","note":"en chemise"},{"id":"thym","qty":3,"unit":"brin"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Sortez le rôti 30 min avant. Dans une cocotte, faites mousser 30 g de beurre à feu moyen-vif et dorez le rôti 10 min sur toutes ses faces. Salez, poivrez.","Ajoutez les grenailles entières, l'ail, le thym, le laurier et 150 ml de bouillon. Couvrez et cuisez 1 h à feu doux en retournant le rôti et les pommes de terre toutes les 20 min (ou au four à 170 °C). Le cœur doit atteindre 65 °C.","Pendant ce temps, faites revenir les lardons 3 min dans une casserole, ajoutez les oignons nouveaux et les carottes avec 15 g de beurre et faites suer 5 min.","Ajoutez les petits pois, la laitue et le reste du bouillon. Couvrez et laissez braiser 20 min à feu doux : les pois doivent être fondants et la laitue confite. Liez avec le reste du beurre.","Sortez le rôti, enveloppez-le de papier aluminium et laissez reposer 10 min. Déglacez la cocotte avec 3 cuillères d'eau en grattant les sucs pour obtenir un jus.","Tranchez le rôti, nappez de jus et servez avec les grenailles et les petits pois."],"tags":["week-end","familial","riche en protéines","réconfortant"],"seasons":["printemps","ete"],"technique":"roti","flavors":["lacte","herbace"]},{"id":"fr2-cote-veau-grand-mere","name":"Côtes de veau grand-mère, lardons, champignons et pommes rissolées","description":"Épaisses côtes de veau poêlées au beurre et garnies à la manière des grand-mères : lardons, champignons, petites échalotes et pommes rissolées, le tout lié au jus de cuisson.","emoji":"🍖","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":35,"difficulty":"facile","servings":2,"ingredients":[{"id":"veau-cote","qty":2,"unit":"piece","note":"épaisses de 3 cm"},{"id":"lardons","qty":80,"unit":"g"},{"id":"champignon","qty":200,"unit":"g","note":"petits, entiers"},{"id":"echalote","qty":4,"unit":"piece","note":"entières, pelées"},{"id":"pomme-de-terre","qty":500,"unit":"g","note":"en cubes de 2 cm"},{"id":"beurre","qty":40,"unit":"g"},{"id":"graisse-canard","qty":1,"unit":"cas"},{"id":"bouillon-volaille","qty":100,"unit":"ml"},{"id":"thym","qty":2,"unit":"brin"},{"id":"persil","qty":5,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Précuisez les cubes de pommes de terre 5 min dans l'eau bouillante salée, égouttez et séchez-les.","Faites-les rissoler 20 min dans la graisse de canard à feu moyen dans une grande poêle, en les retournant souvent, jusqu'à ce qu'ils soient dorés sur toutes les faces. Salez.","Pendant ce temps, faites mousser 25 g de beurre dans une sauteuse à feu moyen-vif. Salez les côtes et saisissez-les 4 min par face, en les arrosant de beurre ; à cœur, le veau doit rester rosé (60 °C). Réservez sous aluminium.","Dans la même sauteuse, faites revenir les lardons, les échalotes et les champignons 8 min à feu moyen avec le thym, jusqu'à ce que tout soit doré.","Versez le bouillon, grattez les sucs et laissez réduire 2 min. Ajoutez le reste du beurre et le jus rendu par les côtes, poivrez.","Remettez les côtes 1 min dans la garniture pour les réchauffer, parsemez de persil et servez avec les pommes rissolées."],"tags":["une poêle","riche en protéines","week-end","calorique"],"seasons":["automne"],"technique":"poele","flavors":["umami","grille"]},{"id":"fr2-roti-porc-pruneaux-puree","name":"Rôti de porc aux pruneaux, purée au beurre","description":"Un rôti d'échine moelleux cuit au four avec des oignons et des pruneaux qui confisent dans le jus, servi avec une purée maison. Sucré-salé de tradition.","emoji":"🐖","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":90,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"porc-echine","qty":900,"unit":"g","note":"rôti dans l'échine, ficelé"},{"id":"pruneaux","qty":180,"unit":"g","note":"dénoyautés"},{"id":"oignon","qty":2,"unit":"piece","note":"en quartiers"},{"id":"vin-blanc","qty":150,"unit":"ml"},{"id":"bouillon-volaille","qty":200,"unit":"ml"},{"id":"pomme-de-terre-farineuse","qty":900,"unit":"g"},{"id":"lait","qty":200,"unit":"ml"},{"id":"beurre","qty":45,"unit":"g"},{"id":"thym","qty":3,"unit":"brin"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 180 °C. Salez et poivrez le rôti, faites-le dorer 8 min dans un plat allant sur le feu (ou une cocotte) avec 10 g de beurre à feu vif.","Disposez autour les oignons, le thym et le laurier. Versez le vin blanc et le bouillon et enfournez 1 h, en arrosant toutes les 20 min.","Ajoutez les pruneaux dans le jus et poursuivez 30 min : le cœur du rôti doit atteindre 68 °C et le jus être sirupeux.","Pendant ce temps, cuisez les pommes de terre épluchées 25 min dans l'eau salée, égouttez-les et écrasez-les avec 35 g de beurre et le lait chaud jusqu'à obtenir une purée lisse.","Laissez reposer le rôti 10 min sous aluminium, puis tranchez-le.","Servez les tranches nappées de jus aux pruneaux et d'oignons fondus, avec la purée."],"tags":["week-end","familial","four","réconfortant","calorique"],"seasons":["automne","hiver"],"technique":"roti","flavors":["sucre","reconfortant"],"tips":"Les restes froids, finement tranchés, se mangent avec une salade et des cornichons."},{"id":"fr2-filet-mignon-croute-duxelles","name":"Filet mignon en croûte maison, duxelles et jambon cru","description":"Le filet mignon des grandes occasions : enveloppé de duxelles de champignons et de jambon cru dans une pâte brisée pur beurre faite maison, doré au four. Haricots verts au beurre.","emoji":"🥧","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":45,"cookTime":50,"restTime":30,"difficulty":"intermediaire","servings":4,"ingredients":[{"id":"porc-filet-mignon","qty":800,"unit":"g","note":"2 filets mignons"},{"id":"farine","qty":250,"unit":"g"},{"id":"beurre","qty":175,"unit":"g","note":"dont 125 g froid pour la pâte"},{"id":"eau","qty":60,"unit":"ml","note":"glacée"},{"id":"jaune-oeuf","qty":2,"unit":"piece"},{"id":"champignon","qty":300,"unit":"g","note":"hachés finement"},{"id":"echalote","qty":2,"unit":"piece","note":"hachées"},{"id":"jambon-cru","qty":6,"unit":"tranche"},{"id":"moutarde","qty":1,"unit":"cas"},{"id":"haricots-verts","qty":500,"unit":"g"},{"id":"thym","qty":2,"unit":"brin"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Pâte : sablez du bout des doigts la farine, 1 pincée de sel et 125 g de beurre froid en dés. Ajoutez 1 jaune et l'eau glacée, rassemblez en boule sans pétrir. Filmez et réservez 30 min au réfrigérateur.","Duxelles : faites revenir les échalotes et les champignons dans 15 g de beurre à feu vif avec le thym, 10 min, jusqu'à ce que toute l'eau soit évaporée et le mélange sec. Salez, poivrez, laissez refroidir.","Salez et poivrez les filets, saisissez-les 4 min dans 15 g de beurre à feu vif sur toutes les faces. Laissez tiédir et badigeonnez-les de moutarde.","Préchauffez le four à 200 °C. Abaissez la pâte en un rectangle de 3 mm. Disposez les tranches de jambon cru en les chevauchant, étalez la duxelles, posez les filets tête-bêche et roulez le tout. Soudez les bords, faites une cheminée et dorez au jaune battu.","Enfournez 30 à 35 min jusqu'à ce que la pâte soit bien dorée (cœur de la viande à 65 °C). Laissez reposer 10 min avant de trancher avec un couteau-scie.","Pendant la cuisson, cuisez les haricots verts 8 min dans l'eau bouillante salée, égouttez et enrobez-les du reste de beurre.","Servez en tranches épaisses avec les haricots verts."],"tags":["week-end","four","familial","riche en protéines","calorique"],"seasons":["automne","hiver"],"technique":"four","flavors":["umami","reconfortant"],"tips":"Le roulé peut être monté le matin et gardé filmé au réfrigérateur ; dorez-le juste avant d'enfourner."},{"id":"fr2-cote-porc-charcutiere-coquillettes","name":"Côtes de porc sauce charcutière, coquillettes au beurre","description":"Côtes de porc dorées, sauce brune aux oignons, moutarde et cornichons qui pique juste ce qu'il faut. Avec des coquillettes au beurre, le repas de semaine parfait.","emoji":"🐖","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":10,"cookTime":25,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"porc-cote","qty":2,"unit":"piece","note":"épaisses"},{"id":"oignon","qty":1,"unit":"piece","note":"ciselé"},{"id":"cornichon","qty":50,"unit":"g","note":"en rondelles"},{"id":"moutarde","qty":1,"unit":"cas"},{"id":"vin-blanc","qty":100,"unit":"ml"},{"id":"bouillon-boeuf","qty":120,"unit":"ml"},{"id":"concentre-tomate","qty":1,"unit":"cac"},{"id":"beurre","qty":30,"unit":"g"},{"id":"pates","qty":170,"unit":"g","note":"coquillettes"},{"id":"persil","qty":5,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Mettez une grande casserole d'eau salée à bouillir pour les coquillettes.","Entaillez le gras des côtes tous les 2 cm pour éviter qu'elles ne se recroquevillent. Salez-les et saisissez-les 5 min par face dans 10 g de beurre à feu moyen-vif, jusqu'à ce qu'elles soient bien dorées. Réservez sous aluminium.","Dans la même poêle, faites fondre l'oignon 4 min à feu moyen. Déglacez au vin blanc et laissez réduire de moitié (2 min).","Ajoutez le bouillon et le concentré de tomate, laissez réduire 4 min jusqu'à ce que la sauce nappe la cuillère. Hors du feu, incorporez moutarde, cornichons et 10 g de beurre. Poivrez.","Pendant ce temps, cuisez les coquillettes 9 min, égouttez-les et enrobez-les du reste du beurre.","Remettez les côtes et leur jus dans la sauce 1 min, parsemez de persil et servez avec les coquillettes."],"tags":["économique","familial","une poêle","riche en protéines"],"seasons":[],"technique":"poele","flavors":["acidule","umami"]},{"id":"fr2-carre-agneau-persille","name":"Carré d'agneau en croûte persillée, grenailles à l'ail et haricots verts","description":"Le carré d'agneau de brasserie : saisi, couvert d'une croûte de chapelure, persil, ail et moutarde, rôti rosé. Grenailles confites à l'ail et haricots verts au beurre.","emoji":"🐑","category":"plat","mealTypes":["diner","dejeuner"],"cuisine":"francaise","prepTime":20,"cookTime":40,"restTime":5,"difficulty":"intermediaire","servings":2,"ingredients":[{"id":"agneau-cotelette","qty":550,"unit":"g","note":"1 carré de 6 à 8 côtes, manchonné"},{"id":"panure","qty":20,"unit":"g"},{"id":"persil","qty":20,"unit":"g"},{"id":"ail","qty":6,"unit":"gousse","note":"dont 4 en chemise"},{"id":"moutarde","qty":1,"unit":"cas"},{"id":"beurre","qty":25,"unit":"g"},{"id":"pomme-de-terre","qty":450,"unit":"g","note":"grenailles"},{"id":"graisse-canard","qty":2,"unit":"cac"},{"id":"haricots-verts","qty":250,"unit":"g"},{"id":"thym","qty":3,"unit":"brin"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 200 °C. Enrobez les grenailles coupées en deux de graisse de canard avec l'ail en chemise, le thym et du sel, et enfournez 35 min en remuant à mi-cuisson.","Mixez la chapelure, le persil, 2 gousses d'ail et 15 g de beurre mou en une pâte verte. Salez, poivrez.","Salez le carré et saisissez-le côté gras 4 min dans une poêle à feu moyen-vif, puis 1 min sur chaque autre face, jusqu'à ce que le gras soit doré.","Badigeonnez le côté gras de moutarde et pressez la croûte persillée dessus en une couche régulière.","Enfournez le carré à côté des grenailles 15 à 18 min (cœur à 55 °C pour rosé). Laissez reposer 5 min sous aluminium avant de découper entre les côtes.","Pendant ce temps, cuisez les haricots verts 7 min dans l'eau bouillante salée, égouttez et roulez-les dans le reste du beurre.","Partagez les côtes avec les grenailles et les haricots verts, en écrasant l'ail confit sur les pommes de terre."],"tags":["week-end","four","riche en protéines","calorique"],"seasons":["printemps"],"technique":"roti","flavors":["herbace","grille"]},{"id":"fr2-choucroute-de-la-mer","name":"Choucroute de la mer au beurre blanc","description":"La version alsacienne marine : choucroute braisée au riesling, haddock, saumon et cabillaud cuits à la vapeur dessus, pommes de terre et beurre blanc à l'échalote.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":75,"difficulty":"intermediaire","servings":4,"ingredients":[{"id":"choucroute","qty":1000,"unit":"g","note":"crue, rincée et essorée"},{"id":"haddock","qty":300,"unit":"g","note":"en 4 morceaux"},{"id":"saumon","qty":300,"unit":"g","note":"en 4 morceaux"},{"id":"cabillaud","qty":300,"unit":"g","note":"en 4 morceaux"},{"id":"pomme-de-terre","qty":900,"unit":"g","note":"à chair ferme"},{"id":"vin-blanc","qty":350,"unit":"ml","note":"riesling, dont 100 ml pour le beurre blanc"},{"id":"oignon","qty":1,"unit":"piece","note":"émincé"},{"id":"echalote","qty":2,"unit":"piece","note":"ciselées très finement"},{"id":"graisse-canard","qty":2,"unit":"cas"},{"id":"beurre","qty":150,"unit":"g","note":"froid, en dés, pour le beurre blanc"},{"id":"graines-fenouil","qty":1,"unit":"cac","note":"baies de genièvre ou carvi"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"vinaigre-cidre","qty":2,"unit":"cas","note":"vinaigre de vin blanc"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Dans une grande cocotte, faites fondre l'oignon 5 min dans la graisse de canard à feu moyen. Ajoutez la choucroute, le laurier, le carvi, 250 ml de riesling et 200 ml d'eau. Couvrez et laissez braiser 1 h à feu doux en remuant de temps en temps.","30 min avant la fin, cuisez les pommes de terre épluchées 25 min à la vapeur.","Beurre blanc : dans une petite casserole, faites réduire les échalotes avec le reste du vin et le vinaigre à feu moyen jusqu'à ce qu'il ne reste qu'une cuillère à soupe de liquide (8 min). À feu très doux, incorporez le beurre froid dé par dé en fouettant sans cesse : la sauce doit être mousseuse et nappante, sans jamais bouillir. Salez, poivrez et gardez au bain-marie tiède.","Salez légèrement les poissons. Posez-les sur la choucroute, couvrez et laissez cuire à la vapeur 8 à 10 min à feu doux : la chair doit être nacrée et s'effeuiller.","Dressez la choucroute dans des assiettes chaudes, déposez un morceau de chaque poisson, les pommes de terre, et nappez de beurre blanc."],"tags":["week-end","fermenté","riche en protéines","sans gluten","calorique"],"seasons":["automne","hiver"],"technique":"braise","flavors":["acidule","iode","fume"]},{"id":"fr2-jambon-madere-epinards","name":"Jambon braisé sauce madère, épinards au beurre et pommes vapeur","description":"Le plat de bistrot d'antan : épaisses tranches de jambon à l'os réchauffées dans une sauce brune au madère et aux champignons, épinards fondus au beurre et pommes vapeur.","emoji":"🍖","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":10,"cookTime":30,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"jambon-blanc","qty":340,"unit":"g","note":"2 tranches épaisses de jambon à l'os"},{"id":"vin-rouge","qty":120,"unit":"ml","note":"madère"},{"id":"bouillon-boeuf","qty":200,"unit":"ml"},{"id":"champignon","qty":150,"unit":"g","note":"émincés"},{"id":"echalote","qty":1,"unit":"piece","note":"ciselée"},{"id":"concentre-tomate","qty":1,"unit":"cac"},{"id":"fecule-mais","qty":1,"unit":"cac","note":"délayée dans un peu d'eau froide"},{"id":"beurre","qty":45,"unit":"g"},{"id":"epinard","qty":19.25,"unit":"g","note":"frais, équeutés"},{"id":"pomme-de-terre","qty":600,"unit":"g"},{"id":"muscade","qty":1,"unit":"pincee"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"},{"id":"parmesan","qty":30,"unit":"g","note":"le calcium limite l’absorption des oxalates"}],"steps":["Cuisez les pommes de terre épluchées 25 min à la vapeur.","Blanchissez les épinards 2 min dans l’eau bouillante salée, égouttez-les et jetez l’eau de cuisson (cela élimine une bonne partie des oxalates solubles).","Sauce : faites revenir l'échalote et les champignons 5 min dans 15 g de beurre à feu moyen. Ajoutez le concentré de tomate, puis le madère, et faites réduire de moitié (3 min).","Versez le bouillon, laissez frémir 5 min, puis liez avec la fécule délayée en remuant : la sauce doit napper la cuillère. Poivrez.","Glissez les tranches de jambon dans la sauce, couvrez et laissez-les se réchauffer 6 à 8 min à feu très doux, sans bouillir, en les retournant une fois.","Pendant ce temps, faites tomber les épinards 2 min dans 20 g de beurre à feu vif, salez et ajoutez la muscade.","Ajoutez le reste du beurre à la sauce hors du feu et servez le jambon nappé, avec les épinards et les pommes vapeur.","Servez parsemé de parmesan râpé (son calcium limite l’absorption des oxalates)."],"tags":["rapide","familial","riche en protéines","sans gluten"],"seasons":["automne","hiver","printemps"],"technique":"braise","flavors":["umami","reconfortant"]},{"id":"fr2-poulet-roti-dimanche","name":"Poulet rôti du dimanche et pommes de terre au jus","description":"Le poulet fermier rôti au beurre, peau croustillante, avec des pommes de terre qui cuisent sous lui dans son jus. Une salade verte à côté, et tout le monde est content.","emoji":"🍗","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":90,"restTime":10,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"poulet-entier","qty":1,"unit":"piece","note":"fermier, environ 1,6 kg"},{"id":"pomme-de-terre","qty":1000,"unit":"g","note":"à chair ferme, en quartiers"},{"id":"beurre","qty":50,"unit":"g","note":"mou"},{"id":"ail","qty":6,"unit":"gousse","note":"en chemise"},{"id":"thym","qty":4,"unit":"brin"},{"id":"citron","qty":1,"unit":"piece"},{"id":"laitue","qty":200,"unit":"g","note":"en salade"},{"id":"huile-olive","qty":2,"unit":"cas","note":"pour la vinaigrette"},{"id":"moutarde","qty":1,"unit":"cac"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Sortez le poulet 1 h avant. Préchauffez le four à 210 °C.","Massez le poulet avec le beurre mou, salez-le généreusement dedans et dehors. Glissez dans la cavité le citron piqué à la fourchette et 2 brins de thym.","Disposez les quartiers de pommes de terre et l'ail au fond d'un plat, salez, ajoutez le reste du thym et 100 ml d'eau. Posez le poulet dessus, sur le flanc.","Enfournez 25 min, retournez-le sur l'autre flanc 25 min, puis sur le dos 30 à 40 min, en l'arrosant de jus à chaque fois et en remuant les pommes de terre. Le jus qui s'écoule de la cuisse piquée doit être clair.","Laissez reposer le poulet 10 min sous aluminium, porte du four entrouverte, les pommes de terre au chaud.","Préparez la vinaigrette (moutarde, sel, huile) et assaisonnez la salade. Découpez le poulet et servez avec les pommes de terre nappées de jus et la salade."],"tags":["week-end","familial","four","riche en protéines","réconfortant"],"seasons":[],"technique":"roti","flavors":["grille","reconfortant"],"tips":"Gardez la carcasse pour un bouillon de volaille maison."},{"id":"fr2-poulet-vallee-auge","name":"Poulet vallée d'Auge au cidre, à la crème et aux champignons, riz","description":"Le poulet normand : cuisses dorées au beurre, mijotées au cidre et nappées d'une sauce à la crème crue et aux champignons, avec des quartiers de pomme poêlés et un riz blanc.","emoji":"🍎","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":50,"difficulty":"facile","servings":4,"ingredients":[{"id":"poulet-cuisse","qty":4,"unit":"piece"},{"id":"cidre","qty":300,"unit":"ml","note":"brut ; un trait de calvados si vous en avez"},{"id":"creme-fraiche","qty":200,"unit":"ml","note":"crème crue d'Isigny"},{"id":"champignon-forestier","qty":250,"unit":"g","note":"girolles, ou morilles réhydratées"},{"id":"echalote","qty":3,"unit":"piece","note":"ciselées"},{"id":"pomme","qty":2,"unit":"piece","note":"en quartiers"},{"id":"beurre","qty":50,"unit":"g"},{"id":"riz-blanc","qty":280,"unit":"g"},{"id":"thym","qty":2,"unit":"brin"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Salez les cuisses et faites-les dorer côté peau 8 min dans 20 g de beurre à feu moyen-vif dans une cocotte, puis 3 min côté chair. Réservez et retirez l'excès de gras.","Faites suer les échalotes 3 min dans la cocotte. Remettez les cuisses, versez le cidre, ajoutez le thym. Couvrez et laissez mijoter 30 min à feu doux.","Pendant ce temps, poêlez les champignons 5 min à feu vif dans 15 g de beurre, salez. Dans une autre poêle, dorez les quartiers de pomme 6 min dans le reste du beurre.","Cuisez le riz 12 min dans l'eau bouillante salée et égouttez.","Retirez les cuisses. Faites réduire le jus de cuisson de moitié à feu vif (5 min), ajoutez la crème et les champignons et laissez bouillonner 3 min jusqu'à ce que la sauce nappe la cuillère. Poivrez.","Remettez les cuisses dans la sauce 2 min et servez avec les pommes poêlées et le riz."],"tags":["week-end","familial","calorique","réconfortant"],"seasons":["automne"],"technique":"braise","flavors":["cremeux","fruite"]},{"id":"fr2-poulet-vinaigre-lyonnais","name":"Poulet au vinaigre à la lyonnaise, pommes sautées","description":"Le classique des bouchons : poulet découpé, doré puis cuit au vinaigre de vin, échalotes et tomate, jusqu'à une sauce brillante et acidulée adoucie d'une touche de crème.","emoji":"🍗","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":50,"difficulty":"facile","servings":4,"ingredients":[{"id":"poulet-entier","qty":1,"unit":"piece","note":"découpé en 8 morceaux"},{"id":"vinaigre-cidre","qty":100,"unit":"ml","note":"vinaigre de vin rouge"},{"id":"echalote","qty":5,"unit":"piece","note":"ciselées"},{"id":"tomate","qty":2,"unit":"piece","note":"mondées, concassées"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"vin-blanc","qty":150,"unit":"ml"},{"id":"creme-fraiche","qty":60,"unit":"ml"},{"id":"beurre","qty":40,"unit":"g"},{"id":"pomme-de-terre","qty":900,"unit":"g","note":"en rondelles épaisses"},{"id":"graisse-canard","qty":2,"unit":"cas"},{"id":"estragon","qty":5,"unit":"g","note":"ou persil"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Salez et poivrez les morceaux de poulet. Faites-les dorer 10 min dans 30 g de beurre dans une sauteuse à feu moyen-vif, côté peau d'abord, jusqu'à ce qu'ils soient bien colorés.","Ajoutez les échalotes et l'ail, laissez fondre 3 min. Versez le vinaigre en vous tenant à distance et laissez réduire de moitié 3 min, en retournant les morceaux.","Ajoutez le vin blanc et les tomates, couvrez et laissez cuire 30 min à feu doux.","Pendant ce temps, précuisez les rondelles de pommes de terre 6 min à l'eau salée, égouttez, puis faites-les sauter 20 min dans la graisse de canard à feu moyen jusqu'à ce qu'elles soient dorées.","Retirez le poulet. Faites réduire la sauce 5 min à feu vif jusqu'à ce qu'elle soit sirupeuse, puis incorporez la crème et le reste du beurre en fouettant.","Nappez le poulet de sauce, parsemez d'estragon et servez avec les pommes sautées."],"tags":["week-end","familial","riche en protéines","réconfortant"],"seasons":["ete","automne"],"technique":"braise","flavors":["acidule","umami"]},{"id":"fr2-cordon-bleu-maison","name":"Cordon bleu maison, purée de céleri et pommes de terre","description":"Un vrai cordon bleu fait maison : blanc de poulet ouvert en portefeuille, farci de jambon et de comté, pané et doré au beurre clarifié. Avec une purée de céleri-pomme de terre.","emoji":"🧀","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":30,"difficulty":"facile","servings":2,"ingredients":[{"id":"poulet-blanc","qty":2,"unit":"piece","note":"gros blancs"},{"id":"jambon-blanc","qty":2,"unit":"piece","note":"tranches"},{"id":"comte","qty":50,"unit":"g","note":"en fines tranches"},{"id":"oeuf","qty":1,"unit":"piece"},{"id":"farine","qty":25,"unit":"g"},{"id":"panure","qty":60,"unit":"g"},{"id":"beurre-clarifie","qty":30,"unit":"g"},{"id":"pomme-de-terre-farineuse","qty":350,"unit":"g"},{"id":"celeri-rave","qty":250,"unit":"g"},{"id":"lait","qty":80,"unit":"ml"},{"id":"beurre","qty":25,"unit":"g"},{"id":"citron","qty":0.5,"unit":"piece","note":"en quartiers"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Purée : cuisez pommes de terre et céleri-rave épluchés et coupés en dés 25 min dans l'eau salée. Égouttez et écrasez avec le beurre et le lait chaud. Gardez au chaud.","Ouvrez chaque blanc en portefeuille dans l'épaisseur sans le séparer, puis aplatissez-le entre deux feuilles de papier cuisson à 1 cm d'épaisseur.","Garnissez une moitié d'une tranche de jambon pliée et de comté, en laissant 1 cm de bord libre. Refermez et pressez les bords.","Panez : farine, puis œuf battu salé, puis chapelure, en appuyant bien sur les bords pour sceller. Laissez reposer 10 min au frais si possible.","Faites chauffer le beurre clarifié à feu moyen dans une grande poêle. Cuisez les cordons bleus 6 à 7 min par face, jusqu'à ce que la panure soit dorée et croustillante et le fromage fondant au cœur.","Égouttez sur du papier absorbant et servez avec la purée et un quartier de citron."],"tags":["familial","riche en protéines","une poêle","réconfortant"],"seasons":["automne","hiver"],"technique":"friture-legere","flavors":["lacte","reconfortant"]},{"id":"fr2-canard-orange-puree-celeri","name":"Canard à l'orange, écrasé de pommes de terre au céleri","description":"Le grand classique en version magret : chair rosée et peau croustillante, sauce bigarade aigre-douce à l'orange et au miel, et un écrasé de pommes de terre au céleri.","emoji":"🦆","category":"plat","mealTypes":["diner","dejeuner"],"cuisine":"francaise","prepTime":20,"cookTime":30,"difficulty":"facile","servings":2,"ingredients":[{"id":"canard-magret","qty":400,"unit":"g","note":"1 gros magret"},{"id":"orange","qty":3,"unit":"piece","note":"1 pour le zeste et les suprêmes, 2 pressées"},{"id":"miel","qty":1,"unit":"cas"},{"id":"vinaigre-cidre","qty":2,"unit":"cas","note":"vinaigre de vin"},{"id":"bouillon-volaille","qty":150,"unit":"ml"},{"id":"beurre","qty":30,"unit":"g"},{"id":"pomme-de-terre","qty":450,"unit":"g"},{"id":"celeri-rave","qty":200,"unit":"g"},{"id":"lait","qty":60,"unit":"ml"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Cuisez pommes de terre et céleri épluchés en morceaux 25 min dans l'eau salée, égouttez et écrasez grossièrement à la fourchette avec 15 g de beurre et le lait chaud.","Prélevez le zeste d'une orange en fines lanières, blanchissez-les 1 min. Levez les suprêmes de cette orange et pressez les deux autres.","Quadrillez la peau du magret sans entailler la chair, salez. Posez-le côté peau dans une poêle froide, allumez à feu moyen et cuisez 8 à 10 min en retirant régulièrement la graisse fondue, jusqu'à ce que la peau soit dorée et croustillante. Retournez 4 min côté chair, puis laissez reposer 5 min sous aluminium.","Videz la poêle. Faites caraméliser le miel 1 min à feu moyen, déglacez au vinaigre (attention aux projections), puis ajoutez jus d'orange et bouillon. Faites réduire 8 min jusqu'à consistance sirupeuse.","Hors du feu, montez la sauce avec le reste du beurre, ajoutez les zestes et les suprêmes. Poivrez.","Tranchez le magret, nappez de sauce à l'orange et servez avec l'écrasé."],"tags":["week-end","riche en protéines","une poêle","calorique"],"seasons":["hiver"],"technique":"poele","flavors":["fruite","acidule","sucre"],"tips":"La graisse de canard récupérée se garde au réfrigérateur pour les pommes sarladaises."},{"id":"fr2-parmentier-confit-canard","name":"Parmentier de confit de canard à l'échalote","description":"Le hachis Parmentier du Sud-Ouest : confit de canard effiloché et fondu avec des échalotes, sous une purée au lait et une croûte de chapelure dorée à la graisse de canard.","emoji":"🦆","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":30,"cookTime":50,"difficulty":"facile","servings":4,"ingredients":[{"id":"canard-cuisse","qty":4,"unit":"piece","note":"confites"},{"id":"pomme-de-terre-farineuse","qty":1100,"unit":"g"},{"id":"lait","qty":250,"unit":"ml"},{"id":"beurre","qty":30,"unit":"g"},{"id":"echalote","qty":4,"unit":"piece","note":"ciselées"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"persil","qty":15,"unit":"g","note":"haché"},{"id":"panure","qty":30,"unit":"g"},{"id":"muscade","qty":1,"unit":"pincee"},{"id":"laitue","qty":200,"unit":"g","note":"salade verte d'accompagnement","optional":true},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Réchauffez les cuisses confites 10 min dans une poêle à feu doux pour faire fondre leur graisse. Retirez peau et os, effilochez la chair à la fourchette. Gardez 2 cuillères de graisse.","Cuisez les pommes de terre épluchées 25 min dans l'eau salée, égouttez et écrasez avec le beurre, le lait chaud et la muscade. Poivrez.","Dans 1 cuillère de graisse de canard, faites fondre les échalotes 5 min à feu moyen, ajoutez l'ail et le canard effiloché et laissez dorer 5 min. Ajoutez le persil, rectifiez sel et poivre.","Préchauffez le four à 200 °C. Étalez le canard dans un plat, couvrez de purée en lissant à la fourchette.","Mélangez la chapelure avec la dernière cuillère de graisse de canard et parsemez-la sur la purée.","Enfournez 25 min, jusqu'à ce que le dessus soit doré et croustillant. Servez avec une salade verte."],"tags":["familial","four","réconfortant","batch cooking","préparation à l’avance"],"seasons":["automne","hiver"],"technique":"four","flavors":["reconfortant","umami"]},{"id":"fr2-canard-navets-pommes-vapeur","name":"Cuisses de canard aux navets glacés, pommes vapeur","description":"Un plat de grand-mère trop oublié : cuisses de canard braisées au vin blanc, navets glacés au beurre et au jus de cuisson, petites pommes vapeur.","emoji":"🦆","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":90,"difficulty":"facile","servings":4,"ingredients":[{"id":"canard-cuisse","qty":4,"unit":"piece","note":"fraîches"},{"id":"navet","qty":6,"unit":"piece","note":"navets nouveaux, en quartiers"},{"id":"carotte","qty":2,"unit":"piece"},{"id":"oignon","qty":1,"unit":"piece"},{"id":"vin-blanc","qty":200,"unit":"ml"},{"id":"bouillon-volaille","qty":300,"unit":"ml"},{"id":"sucre","qty":1,"unit":"cac"},{"id":"beurre","qty":25,"unit":"g"},{"id":"pomme-de-terre","qty":800,"unit":"g"},{"id":"thym","qty":3,"unit":"brin"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Piquez la peau des cuisses à la fourchette, salez. Faites-les dorer côté peau 10 min dans une cocotte à feu moyen sans matière grasse, jusqu'à ce que la peau soit brune et que la graisse ait fondu. Retournez 2 min. Réservez et ne gardez que 2 cuillères de graisse.","Faites revenir oignon et carottes en rondelles 4 min dans cette graisse. Remettez les cuisses, versez le vin blanc et le bouillon, ajoutez thym et laurier.","Couvrez et laissez braiser 1 h à feu doux.","Pendant ce temps, dans une sauteuse, mettez les navets avec le beurre, le sucre, une pincée de sel et de l'eau à mi-hauteur. Cuisez à découvert à feu moyen 15 à 20 min jusqu'à évaporation : ils doivent être tendres et brillants. Roulez-les dans ce glaçage 2 min.","Ajoutez les navets glacés dans la cocotte et poursuivez 15 min à découvert pour réduire la sauce. Cuisez les pommes de terre épluchées 25 min à la vapeur.","Dégraissez la sauce à la cuillère, poivrez et servez les cuisses avec les navets et les pommes vapeur."],"tags":["mijoté","week-end","familial","réconfortant"],"seasons":["printemps","automne"],"technique":"braise","flavors":["umami","sucre"]},{"id":"fr2-lapin-moutarde-tagliatelles","name":"Lapin à la moutarde, tagliatelles au beurre","description":"Le lapin des dimanches : morceaux dorés, nappés de moutarde forte et mijotés au vin blanc avec des lardons, terminés à la crème. Tagliatelles pour la sauce.","emoji":"🐇","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":60,"difficulty":"facile","servings":4,"ingredients":[{"id":"lapin","qty":1400,"unit":"g","note":"découpé en morceaux"},{"id":"moutarde","qty":4,"unit":"cas","note":"forte + à l'ancienne"},{"id":"creme-fraiche","qty":200,"unit":"ml"},{"id":"vin-blanc","qty":200,"unit":"ml"},{"id":"echalote","qty":3,"unit":"piece"},{"id":"lardons","qty":100,"unit":"g"},{"id":"beurre","qty":30,"unit":"g"},{"id":"pates","qty":320,"unit":"g","note":"tagliatelles"},{"id":"thym","qty":3,"unit":"brin"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Badigeonnez les morceaux de lapin de 3 cuillères de moutarde, salez et poivrez. Laissez reposer pendant que vous préparez le reste.","Dans une cocotte, faites revenir les lardons 3 min à feu moyen, ajoutez 20 g de beurre et dorez les morceaux de lapin 8 min en les retournant, jusqu'à ce qu'ils soient blonds.","Ajoutez les échalotes émincées, laissez fondre 2 min, versez le vin blanc et grattez les sucs. Ajoutez le thym, couvrez et laissez mijoter 45 min à feu doux en retournant à mi-cuisson.","Retirez le lapin. Incorporez la crème et la dernière cuillère de moutarde à la sauce et laissez réduire 5 min à feu moyen jusqu'à ce qu'elle nappe la cuillère.","Cuisez les tagliatelles dans l'eau bouillante salée selon le paquet, égouttez et enrobez-les du reste de beurre.","Remettez le lapin dans la sauce 2 min et servez avec les tagliatelles."],"tags":["week-end","familial","riche en protéines","réconfortant"],"seasons":[],"technique":"braise","flavors":["piquant","cremeux"]},{"id":"fr2-lapin-pruneaux-biere","name":"Lapin aux pruneaux à la bière, pommes vapeur","description":"Le lapin du Nord, mijoté à la bière brune avec oignons, pruneaux et une pointe de moutarde jusqu'à une sauce douce et ambrée.","emoji":"🐇","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":80,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"lapin","qty":1400,"unit":"g","note":"découpé en morceaux"},{"id":"pruneaux","qty":150,"unit":"g"},{"id":"biere","qty":330,"unit":"ml","note":"brune ou ambrée"},{"id":"oignon","qty":3,"unit":"piece","note":"émincés"},{"id":"bouillon-volaille","qty":150,"unit":"ml"},{"id":"farine","qty":1,"unit":"cas"},{"id":"beurre","qty":40,"unit":"g"},{"id":"pain-levain","qty":1,"unit":"piece","note":"tranche tartinée de moutarde"},{"id":"moutarde","qty":1,"unit":"cas"},{"id":"pomme-de-terre","qty":1000,"unit":"g"},{"id":"thym","qty":3,"unit":"brin"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Salez et poivrez le lapin, roulez-le légèrement dans la farine. Dorez-le 8 min dans 30 g de beurre dans une cocotte à feu moyen-vif. Réservez.","Faites fondre les oignons 10 min à feu moyen dans le reste du beurre, jusqu'à ce qu'ils soient blonds.","Remettez le lapin, versez la bière et le bouillon, ajoutez thym et laurier. Posez la tranche de pain tartinée de moutarde sur le dessus : elle fondra et liera la sauce.","Couvrez et laissez mijoter 50 min à feu doux. Ajoutez les pruneaux et poursuivez 20 min à découvert, jusqu'à ce que la sauce soit épaisse et brillante.","Pendant ce temps, cuisez les pommes de terre épluchées 25 min à la vapeur.","Mélangez la sauce pour dissoudre le pain, rectifiez l'assaisonnement et servez avec les pommes vapeur."],"tags":["mijoté","familial","réconfortant","batch cooking"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["sucre","reconfortant"]},{"id":"fr2-poisson-pane-maison-puree","name":"Poisson pané maison, purée et sauce tartare","description":"Le vrai poisson pané : bâtonnets de lieu enrobés de chapelure dorée au beurre clarifié, purée au lait et sauce tartare maison au yaourt, cornichons et câpres.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":25,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"cabillaud","qty":400,"unit":"g","note":"lieu ou colin, en bâtonnets épais"},{"id":"oeuf","qty":1,"unit":"piece"},{"id":"farine","qty":30,"unit":"g"},{"id":"panure","qty":70,"unit":"g"},{"id":"beurre-clarifie","qty":40,"unit":"g"},{"id":"pomme-de-terre-farineuse","qty":500,"unit":"g"},{"id":"lait","qty":100,"unit":"ml"},{"id":"beurre","qty":30,"unit":"g"},{"id":"yaourt-grec","qty":80,"unit":"g"},{"id":"cornichon","qty":20,"unit":"g","note":"hachés"},{"id":"capres","qty":1,"unit":"cac"},{"id":"persil","qty":5,"unit":"g"},{"id":"citron","qty":1,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Cuisez les pommes de terre épluchées 20 min dans l'eau salée, égouttez et écrasez-les avec le beurre et le lait chaud. Gardez au chaud.","Sauce tartare : mélangez le yaourt, les cornichons, les câpres, le persil haché, quelques gouttes de citron, sel et poivre.","Séchez les bâtonnets de poisson au papier absorbant et salez-les. Passez-les successivement dans la farine, l'œuf battu puis la chapelure en pressant bien.","Faites chauffer le beurre clarifié dans une grande poêle à feu moyen-vif. Dorez les bâtonnets 2 à 3 min par face, sans les serrer, jusqu'à ce que la panure soit dorée et que la chair se détache en lamelles nacrées.","Égouttez sur du papier absorbant et servez aussitôt avec la purée, la sauce tartare et des quartiers de citron."],"tags":["familial","rapide","riche en protéines","une poêle"],"seasons":[],"technique":"friture-legere","flavors":["lacte","acidule"],"tips":"Les bâtonnets panés crus se congèlent à plat : cuisez-les sans décongeler, 1 min de plus par face."},{"id":"fr2-cabillaud-bordelaise-pommes-fondantes","name":"Cabillaud à la bordelaise, pommes fondantes","description":"Dos de cabillaud cuit au four sous une croûte de chapelure, échalotes, persil et beurre, servi avec des pommes de terre fondantes au bouillon.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":40,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"cabillaud","qty":2,"unit":"piece","note":"dos épais de 180 g"},{"id":"panure","qty":40,"unit":"g"},{"id":"beurre","qty":60,"unit":"g","note":"mou"},{"id":"echalote","qty":2,"unit":"piece","note":"très finement ciselées"},{"id":"persil","qty":15,"unit":"g","note":"haché"},{"id":"ail","qty":1,"unit":"gousse"},{"id":"vin-blanc","qty":80,"unit":"ml"},{"id":"pomme-de-terre","qty":600,"unit":"g","note":"à chair ferme, en tronçons de 3 cm"},{"id":"bouillon-volaille","qty":200,"unit":"ml"},{"id":"citron","qty":0.5,"unit":"piece"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Pommes fondantes : dans une sauteuse, dorez les tronçons de pommes de terre 5 min par face dans 15 g de beurre à feu moyen. Versez le bouillon à mi-hauteur, salez, couvrez et cuisez 20 min à feu doux, puis 5 min à découvert jusqu'à ce que le liquide soit absorbé.","Préchauffez le four à 210 °C. Faites fondre les échalotes 3 min dans 10 g de beurre à feu doux, sans coloration.","Mélangez les échalotes avec la chapelure, le persil, l'ail haché, le reste du beurre mou, sel et poivre, pour obtenir une pâte grumeleuse.","Posez les dos de cabillaud salés dans un plat, versez le vin blanc autour, et couvrez le dessus de chaque morceau d'une couche de croûte en tassant.","Enfournez 12 à 15 min : la croûte doit être dorée et la chair juste nacrée à cœur. Passez 1 min sous le gril si besoin.","Arrosez de quelques gouttes de citron et servez avec les pommes fondantes et le jus du plat."],"tags":["four","riche en protéines","familial"],"seasons":[],"technique":"four","flavors":["herbace","grille"]},{"id":"fr2-saumon-oseille-riz","name":"Saumon à l'oseille, riz blanc","description":"L'escalope de saumon à l'oseille des Troisgros façon maison : pavés juste rosés sur une sauce crème acidulée à l'oseille fondue. Riz blanc pour napper.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":10,"cookTime":20,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"saumon","qty":340,"unit":"g","note":"2 pavés sans peau"},{"id":"oseille","qty":40,"unit":"g","note":"équeutée, en lanières"},{"id":"creme-liquide","qty":150,"unit":"ml"},{"id":"echalote","qty":1,"unit":"piece","note":"ciselée"},{"id":"vin-blanc","qty":80,"unit":"ml"},{"id":"fumet-poisson","qty":100,"unit":"ml"},{"id":"beurre","qty":20,"unit":"g"},{"id":"riz-blanc","qty":150,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"},{"id":"parmesan","qty":30,"unit":"g","note":"le calcium limite l’absorption des oxalates"}],"steps":["Cuisez le riz 12 min dans l'eau bouillante salée, égouttez et gardez au chaud.","Dans une casserole, mettez l'échalote, le vin blanc et le fumet. Faites réduire à feu vif jusqu'à ce qu'il ne reste que 3 cuillères à soupe de liquide (8 min).","Ajoutez la crème et laissez bouillonner 3 min jusqu'à ce qu'elle nappe la cuillère. Hors du feu, ajoutez l'oseille : elle fond et vire au vert kaki en 30 secondes. Salez, poivrez.","Salez les pavés. Faites mousser le beurre dans une poêle à feu moyen-vif et cuisez le saumon 3 min sur la première face, 1 à 2 min sur la seconde : le cœur doit rester rosé et nacré.","Versez la sauce à l'oseille dans les assiettes chaudes, posez le saumon dessus et servez avec le riz.","Servez parsemé de parmesan râpé (son calcium limite l’absorption des oxalates)."],"tags":["rapide","riche en protéines","une poêle","sportif"],"seasons":["printemps","ete"],"technique":"poele","flavors":["acidule","cremeux"]},{"id":"fr2-limande-bonne-femme","name":"Filets de limande bonne femme, champignons et pommes vapeur","description":"Filets de limande pochés au four dans le vin blanc sur un lit d'échalotes et de champignons, puis nappés de leur jus monté à la crème et gratinés.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":30,"difficulty":"facile","servings":2,"ingredients":[{"id":"sole","qty":420,"unit":"g","note":"filets de limande ou de plie"},{"id":"champignon","qty":250,"unit":"g","note":"émincés finement"},{"id":"echalote","qty":2,"unit":"piece","note":"ciselées"},{"id":"vin-blanc","qty":150,"unit":"ml"},{"id":"creme-fraiche","qty":100,"unit":"ml"},{"id":"jaune-oeuf","qty":1,"unit":"piece"},{"id":"beurre","qty":30,"unit":"g"},{"id":"pomme-de-terre","qty":550,"unit":"g"},{"id":"persil","qty":10,"unit":"g","note":"haché"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Lancez la cuisson des pommes de terre épluchées à la vapeur, 25 min.","Préchauffez le four à 190 °C. Beurrez un plat avec 10 g de beurre, répartissez les échalotes et les champignons, salez.","Pliez les filets de limande en deux, salez-les et posez-les sur les champignons. Versez le vin blanc, couvrez d'une feuille de papier cuisson beurrée et enfournez 10 à 12 min : la chair doit être blanche et opaque.","Transvasez délicatement le jus et les champignons dans une casserole en gardant les filets au chaud. Faites réduire de moitié à feu vif (4 min), ajoutez la crème et bouillonnez 2 min. Hors du feu, fouettez le jaune d'œuf et le reste du beurre.","Allumez le gril. Nappez les filets de sauce et passez 2 min sous le gril jusqu'à ce que la surface soit blonde et marbrée.","Parsemez de persil et servez avec les pommes vapeur."],"tags":["familial","four","riche en protéines"],"seasons":[],"technique":"four","flavors":["cremeux","iode"]},{"id":"fr2-maquereaux-vin-blanc-pommes-tiedes","name":"Maquereaux au vin blanc maison, pommes de terre tièdes","description":"Filets de maquereau marinés à chaud dans un court-bouillon au vin blanc, vinaigre, carotte et aromates, servis froids sur des pommes de terre tièdes à l'huile et aux herbes.","emoji":"🐟","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":20,"restTime":720,"difficulty":"facile","servings":2,"ingredients":[{"id":"maquereau","qty":450,"unit":"g","note":"filets (environ 4 maquereaux)"},{"id":"vin-blanc","qty":250,"unit":"ml"},{"id":"vinaigre-cidre","qty":50,"unit":"ml"},{"id":"carotte","qty":1,"unit":"piece","note":"en fines rondelles cannelées"},{"id":"oignon","qty":1,"unit":"piece","note":"en fines rondelles"},{"id":"citron","qty":1,"unit":"piece","note":"en rondelles"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"thym","qty":2,"unit":"brin"},{"id":"coriandre-graines","qty":1,"unit":"cac","note":"graines entières"},{"id":"pomme-de-terre","qty":600,"unit":"g","note":"à chair ferme"},{"id":"huile-olive","qty":2,"unit":"cas"},{"id":"ciboulette","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Court-bouillon : dans une casserole, portez à ébullition le vin blanc, le vinaigre, la carotte, l'oignon, le laurier, le thym, la coriandre, 1 cuillère à café de sel et quelques grains de poivre. Laissez frémir 10 min.","Rangez les filets de maquereau côté peau vers le haut dans un plat creux, en une seule couche. Ajoutez les rondelles de citron.","Versez le court-bouillon bouillant avec ses légumes sur les filets : ils doivent être couverts. La chaleur suffit à les cuire. Laissez refroidir, filmez et réservez au moins 12 h au réfrigérateur.","Le jour même, cuisez les pommes de terre dans leur peau 20 à 25 min à l'eau salée, jusqu'à ce que la lame d'un couteau s'y enfonce sans résistance. Pelez-les tièdes et coupez-les en rondelles.","Arrosez les pommes de terre d'huile d'olive et de 2 cuillères de marinade, salez, poivrez et parsemez de ciboulette.","Servez les filets froids avec carottes et oignons de la marinade sur les pommes de terre tièdes."],"tags":["préparation à l’avance","repas froid","économique","riche en protéines","lunch box"],"seasons":["printemps","ete"],"technique":"poche","flavors":["acidule","iode","frais"],"tips":"Se conserve 4 jours au réfrigérateur dans sa marinade."},{"id":"fr2-moules-normande-cidre-creme","name":"Moules à la normande, cidre, crème et lardons","description":"De grosses moules de bouchot ouvertes au cidre brut avec échalotes, lardons et champignons, puis liées à la crème crue. Pommes de terre au four pour saucer.","emoji":"🦪","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":35,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"moule","qty":2000,"unit":"g","note":"de bouchot, grattées"},{"id":"cidre","qty":250,"unit":"ml","note":"brut"},{"id":"creme-fraiche","qty":120,"unit":"ml"},{"id":"lardons","qty":80,"unit":"g"},{"id":"champignon","qty":150,"unit":"g","note":"émincés"},{"id":"echalote","qty":2,"unit":"piece","note":"ciselées"},{"id":"beurre","qty":15,"unit":"g"},{"id":"pomme-de-terre","qty":600,"unit":"g","note":"en quartiers"},{"id":"graisse-canard","qty":1,"unit":"cas"},{"id":"persil","qty":15,"unit":"g","note":"haché"},{"id":"poivre","qty":1,"unit":"au-gout"},{"id":"sel","qty":1,"unit":"au-gout"}],"steps":["Préchauffez le four à 210 °C. Enrobez les quartiers de pommes de terre de graisse de canard et de sel et rôtissez-les 35 min en les retournant à mi-cuisson.","Grattez et rincez les moules, jetez celles qui restent ouvertes après une pichenette.","Dans un grand faitout, faites dorer les lardons 3 min à feu moyen, ajoutez le beurre, les échalotes et les champignons et faites revenir 5 min.","Montez à feu vif, ajoutez les moules et le cidre, couvrez et cuisez 5 à 6 min en secouant le faitout deux fois : toutes les moules doivent être ouvertes.","Retirez les moules dans un plat creux chaud. Faites bouillir le jus 3 min, ajoutez la crème et laissez bouillonner 2 min. Poivrez, ajoutez le persil.","Versez la sauce sur les moules et servez immédiatement avec les pommes de terre rôties."],"tags":["familial","four","riche en protéines"],"seasons":["ete","automne"],"technique":"vapeur","flavors":["iode","cremeux"]},{"id":"fr2-lotte-armoricaine-riz","name":"Lotte à l'armoricaine, riz blanc","description":"Médaillons de lotte mijotés dans une sauce armoricaine tomatée, vin blanc, échalotes et une pointe de piment d'Espelette, finie au beurre et à l'estragon.","emoji":"🐟","category":"plat","mealTypes":["diner","dejeuner"],"cuisine":"francaise","prepTime":20,"cookTime":35,"difficulty":"intermediaire","servings":2,"ingredients":[{"id":"lotte","qty":450,"unit":"g","note":"en médaillons de 3 cm"},{"id":"tomates-concassees","qty":300,"unit":"g"},{"id":"concentre-tomate","qty":1,"unit":"cas"},{"id":"echalote","qty":2,"unit":"piece","note":"ciselées"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"vin-blanc","qty":150,"unit":"ml"},{"id":"fumet-poisson","qty":150,"unit":"ml"},{"id":"creme-liquide","qty":50,"unit":"ml"},{"id":"huile-olive","qty":1,"unit":"cas"},{"id":"beurre","qty":30,"unit":"g"},{"id":"farine","qty":1,"unit":"cas"},{"id":"piment-espelette","qty":1,"unit":"pincee"},{"id":"estragon","qty":5,"unit":"g"},{"id":"riz-blanc","qty":160,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Retirez la fine membrane grise de la lotte. Épongez les médaillons, salez-les et farinez-les légèrement.","Dans une sauteuse, saisissez-les 2 min par face dans l'huile et 10 g de beurre à feu vif, jusqu'à ce qu'ils soient dorés. Réservez : ils finiront de cuire dans la sauce.","À feu moyen, faites fondre les échalotes et l'ail 3 min. Ajoutez le concentré de tomate et remuez 1 min, puis versez le vin blanc et faites réduire de moitié (3 min).","Ajoutez les tomates, le fumet et le piment d'Espelette. Laissez mijoter 15 min à découvert jusqu'à ce que la sauce épaississe.","Pendant ce temps, cuisez le riz 12 min à l'eau salée et égouttez.","Remettez la lotte dans la sauce avec son jus et cuisez 6 à 8 min à feu doux : la chair doit être blanche et ferme. Hors du feu, ajoutez la crème, le reste du beurre et l'estragon ciselé.","Servez aussitôt avec le riz."],"tags":["week-end","riche en protéines","sans gluten"],"seasons":[],"technique":"mijote","flavors":["iode","umami","epice"],"tips":"Pour une version sans gluten, remplacez la farine par de la fécule."},{"id":"fr2-piperade-jambon-bayonne-oeufs","name":"Piperade basque au jambon de Bayonne et œufs, riz","description":"Poivrons, tomates et oignons fondus longuement à l'huile d'olive et au piment d'Espelette, avec de belles tranches de jambon de Bayonne poêlées et des œufs brouillés à même la piperade.","emoji":"🫑","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":35,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"poivron-rouge","qty":3,"unit":"piece","note":"rouges et verts, en lanières"},{"id":"tomate","qty":4,"unit":"piece","note":"mondées, concassées"},{"id":"oignon","qty":2,"unit":"piece","note":"émincés"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"huile-olive","qty":3,"unit":"cas"},{"id":"piment-espelette","qty":1,"unit":"cac"},{"id":"jambon-cru","qty":6,"unit":"piece","note":"tranches épaisses de jambon de Bayonne"},{"id":"oeuf","qty":5,"unit":"piece"},{"id":"riz-blanc","qty":150,"unit":"g"},{"id":"thym","qty":2,"unit":"brin"},{"id":"sel","qty":1,"unit":"au-gout"}],"steps":["Cuisez le riz 12 min dans l'eau bouillante salée, égouttez et gardez au chaud.","Dans une grande poêle, faites fondre les oignons 5 min dans l'huile d'olive à feu moyen. Ajoutez les poivrons et faites-les fondre 15 min en remuant, jusqu'à ce qu'ils soient très tendres.","Ajoutez les tomates, l'ail écrasé, le thym, le piment d'Espelette et un peu de sel. Laissez compoter 10 min à découvert jusqu'à évaporation presque complète du jus.","Pendant ce temps, poêlez les tranches de jambon 30 secondes par face dans une poêle chaude sans matière grasse. Réservez.","Battez les œufs légèrement, versez-les dans la piperade à feu doux et remuez doucement 2 min à la spatule : ils doivent être pris mais crémeux, en gros flocons.","Servez aussitôt la piperade avec le jambon par-dessus et le riz."],"tags":["rapide","économique","riche en protéines","une poêle","sans gluten"],"seasons":["ete","automne"],"technique":"poele","flavors":["piquant","fruite"]},{"id":"fr2-coeur-veau-braise-carottes","name":"Cœur de veau braisé aux carottes et aux oignons, purée","description":"Le cœur de veau, maigre et très riche en fer, braisé doucement au vin blanc avec carottes, oignons et lardons jusqu'à devenir tendre, servi sur une purée au beurre.","emoji":"🫀","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":20,"cookTime":120,"difficulty":"facile","servings":4,"ingredients":[{"id":"coeur-boeuf","qty":900,"unit":"g","note":"cœur de veau, dénervé, en tranches de 2 cm"},{"id":"lardons","qty":100,"unit":"g"},{"id":"carotte","qty":5,"unit":"piece","note":"en rondelles"},{"id":"oignon","qty":2,"unit":"piece","note":"émincés"},{"id":"ail","qty":2,"unit":"gousse"},{"id":"vin-blanc","qty":200,"unit":"ml"},{"id":"bouillon-boeuf","qty":300,"unit":"ml"},{"id":"concentre-tomate","qty":1,"unit":"cas"},{"id":"farine","qty":1,"unit":"cas"},{"id":"beurre","qty":70,"unit":"g"},{"id":"pomme-de-terre-farineuse","qty":1000,"unit":"g"},{"id":"lait","qty":200,"unit":"ml"},{"id":"thym","qty":3,"unit":"brin"},{"id":"laurier","qty":1,"unit":"feuille"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Parez le cœur : retirez les vaisseaux et la graisse dure, coupez-le en tranches puis en gros morceaux. Épongez-le et salez.","Dans une cocotte, faites revenir les lardons 3 min, ajoutez 15 g de beurre et saisissez le cœur 5 min à feu vif en deux fournées, jusqu'à ce qu'il soit bien coloré. Réservez.","Faites suer oignons et carottes 5 min à feu moyen. Remettez le cœur, saupoudrez de farine, remuez 1 min, puis ajoutez le concentré de tomate et l'ail.","Versez le vin blanc et le bouillon, ajoutez thym et laurier. Couvrez et laissez braiser 1 h 45 à feu très doux : le cœur doit être tendre sous la fourchette.","30 min avant la fin, cuisez les pommes de terre épluchées 25 min à l'eau salée et écrasez-les avec 55 g de beurre et le lait chaud.","Faites réduire la sauce 5 min à découvert si elle est trop liquide, poivrez et servez sur la purée."],"tags":["abats","mijoté","économique","batch cooking","réconfortant"],"seasons":["automne","hiver"],"technique":"braise","flavors":["umami","reconfortant"],"tips":"Le cœur ne supporte que deux cuissons : très rapide (grillé rosé) ou très longue. Entre les deux, il devient caoutchouteux."},{"id":"fr2-tripes-mode-caen","name":"Tripes à la mode de Caen, pommes vapeur","description":"Le monument normand : gras-double et pied de veau cuits des heures au cidre avec carottes, oignons et poireaux, jusqu'à devenir fondants dans un bouillon riche en collagène.","emoji":"🍲","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":30,"cookTime":360,"difficulty":"facile","servings":6,"ingredients":[{"id":"tripes","qty":1500,"unit":"g","note":"gras-double blanchi, en carrés de 4 cm"},{"id":"pied-veau","qty":500,"unit":"g","note":"fendu en deux"},{"id":"carotte","qty":4,"unit":"piece","note":"en rondelles"},{"id":"oignon","qty":3,"unit":"piece","note":"dont 1 piqué de clous de girofle"},{"id":"poireau","qty":2,"unit":"piece","note":"le blanc, en tronçons"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"cidre","qty":750,"unit":"ml","note":"brut ; 4 cl de calvados en option"},{"id":"girofle","qty":3,"unit":"pincee","note":"3 clous"},{"id":"thym","qty":3,"unit":"brin"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"pomme-de-terre","qty":1200,"unit":"g"},{"id":"persil","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Blanchissez le pied de veau 10 min à l'eau bouillante, égouttez et rincez.","Dans une grande cocotte en fonte, disposez la moitié des carottes, des oignons émincés et des poireaux, puis les tripes et le pied de veau, puis le reste des légumes, l'ail, l'oignon piqué, le thym et le laurier.","Versez le cidre et complétez d'eau juste à hauteur. Salez modérément et poivrez.","Portez à frémissement sur le feu, écumez, puis couvrez hermétiquement (luttez le couvercle avec un boudin de farine et d'eau si vous le souhaitez) et enfournez à 140 °C pour 6 h : les tripes doivent être fondantes et le bouillon légèrement collant.","Retirez le pied de veau, désossez-le et remettez sa chair coupée en dés dans les tripes. Retirez l'oignon piqué, le thym et le laurier. Dégraissez la surface à la louche.","Cuisez les pommes de terre épluchées 25 min à la vapeur. Servez les tripes très chaudes dans des assiettes creuses chaudes, parsemées de persil, avec les pommes vapeur."],"tags":["abats","mijoté","riche en collagène","batch cooking","week-end","économique"],"seasons":["automne","hiver"],"technique":"braise","flavors":["reconfortant","umami"],"tips":"Comme tous les mijotés, meilleures réchauffées le lendemain. Se congèlent parfaitement en portions."},{"id":"fr2-haricot-mouton-navets","name":"Haricot de mouton aux navets et pommes de terre","description":"Le ragoût de grand-mère (dont le nom vient de « halicoter », couper en morceaux) : épaule d'agneau mijotée avec navets, petits oignons et pommes de terre qui cuisent dans la sauce.","emoji":"🐑","category":"mijote","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":25,"cookTime":120,"difficulty":"tres-facile","servings":4,"ingredients":[{"id":"agneau-epaule","qty":1000,"unit":"g","note":"épaule ou collier, en morceaux"},{"id":"navet","qty":4,"unit":"piece","note":"en quartiers"},{"id":"oignon-nouveau","qty":10,"unit":"piece","note":"ou petits oignons grelots"},{"id":"pomme-de-terre","qty":900,"unit":"g","note":"à chair ferme, en gros morceaux"},{"id":"ail","qty":3,"unit":"gousse"},{"id":"concentre-tomate","qty":1,"unit":"cas"},{"id":"farine","qty":1,"unit":"cas"},{"id":"bouillon-volaille","qty":800,"unit":"ml"},{"id":"graisse-canard","qty":1,"unit":"cas"},{"id":"thym","qty":3,"unit":"brin"},{"id":"laurier","qty":2,"unit":"feuille"},{"id":"romarin","qty":1,"unit":"brin"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Salez les morceaux d'agneau. Dans une cocotte en fonte, faites chauffer la graisse de canard à feu vif et dorez la viande 8 min en deux fournées, jusqu'à ce qu'elle soit bien brune. Retirez l'excès de gras.","Remettez toute la viande, saupoudrez de farine et remuez 2 min à feu moyen pour la torréfier. Ajoutez le concentré de tomate et l'ail écrasé.","Versez le bouillon chaud à hauteur, ajoutez thym, laurier et romarin. Couvrez et laissez mijoter 1 h à feu doux.","Pendant ce temps, faites dorer les navets et les petits oignons 5 min dans une poêle avec 1 cuillère du gras de la cocotte.","Ajoutez navets, oignons et pommes de terre dans la cocotte : ils doivent être juste couverts (ajoutez un peu d'eau si besoin). Poursuivez 45 min à couvert, puis 10 min à découvert : les pommes de terre doivent être fondantes et la sauce nappante.","Dégraissez à la louche, retirez les herbes, rectifiez l'assaisonnement et servez dans des assiettes creuses."],"tags":["mijoté","week-end","batch cooking","familial","réconfortant","calorique"],"seasons":["automne","hiver"],"technique":"mijote","flavors":["reconfortant","umami"]},{"id":"fr2-foie-genisse-lyonnaise","name":"Foie de génisse à la lyonnaise, pommes de terre sautées","description":"Tranches de foie de génisse saisies rosées, nappées d'oignons confits au beurre et déglacés au vinaigre de vin, avec des pommes de terre sautées.","emoji":"🧅","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":10,"cookTime":30,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"foie-veau","qty":300,"unit":"g","note":"foie de génisse, 2 tranches épaisses"},{"id":"oignon","qty":3,"unit":"piece","note":"émincés finement"},{"id":"vinaigre-cidre","qty":2,"unit":"cas","note":"vinaigre de vin rouge"},{"id":"beurre","qty":40,"unit":"g"},{"id":"farine","qty":1,"unit":"cas"},{"id":"pomme-de-terre","qty":600,"unit":"g","note":"à chair ferme, en rondelles"},{"id":"graisse-canard","qty":1,"unit":"cas"},{"id":"persil","qty":5,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Faites sauter les rondelles de pommes de terre crues dans la graisse de canard à feu moyen, 25 min en les retournant régulièrement, jusqu'à ce qu'elles soient dorées et tendres. Salez.","En parallèle, faites fondre les oignons dans 25 g de beurre à feu moyen-doux, 20 min, jusqu'à ce qu'ils soient blonds et confits. Déglacez avec le vinaigre, laissez réduire 1 min et salez.","Farinez légèrement les tranches de foie et tapotez pour retirer l'excédent.","Faites mousser le reste du beurre à feu vif dans une poêle et saisissez le foie 1 min 30 à 2 min par face : il doit rester rosé à cœur. Salez et poivrez seulement en fin de cuisson.","Nappez le foie des oignons au vinaigre, parsemez de persil et servez avec les pommes sautées."],"tags":["abats","rapide","économique","riche en protéines","une poêle"],"seasons":[],"technique":"poele","flavors":["acidule","sucre"]},{"id":"fr2-oeufs-a-la-tripe","name":"Œufs à la tripe, pommes vapeur","description":"Une recette de grand-mère très ancienne : œufs durs nappés d'une béchamel aux oignons fondus, gratinés au four. Simple, économique et étonnamment savoureuse.","emoji":"🥚","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":15,"cookTime":35,"difficulty":"tres-facile","servings":2,"ingredients":[{"id":"oeuf","qty":6,"unit":"piece"},{"id":"oignon","qty":3,"unit":"piece","note":"émincés finement"},{"id":"beurre","qty":40,"unit":"g"},{"id":"farine","qty":30,"unit":"g"},{"id":"lait","qty":500,"unit":"ml"},{"id":"comte","qty":40,"unit":"g","note":"râpé"},{"id":"muscade","qty":1,"unit":"pincee"},{"id":"pomme-de-terre","qty":500,"unit":"g"},{"id":"persil","qty":10,"unit":"g"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Cuisez les œufs 10 min dans l'eau bouillante, refroidissez-les dans l'eau froide et écalez-les. Coupez-les en quartiers.","Faites fondre les oignons dans le beurre à feu doux 15 min à couvert, sans coloration : ils doivent être translucides et très tendres.","Saupoudrez les oignons de farine, remuez 1 min, puis versez le lait froid en fouettant. Laissez épaissir 5 min à feu moyen en remuant. Assaisonnez de sel, poivre et muscade.","Préchauffez le four à 210 °C. Rangez les quartiers d'œufs dans un plat à gratin, nappez de sauce aux oignons et parsemez de comté.","Enfournez 12 min jusqu'à ce que le dessus soit doré. Pendant ce temps, cuisez les pommes de terre épluchées 25 min à la vapeur.","Parsemez de persil et servez avec les pommes vapeur."],"tags":["économique","familial","réconfortant","four","riche en protéines"],"seasons":["automne","hiver"],"technique":"four","flavors":["lacte","reconfortant"]},{"id":"fr2-flamiche-poireaux-maroilles","name":"Flamiche picarde aux poireaux et au maroilles, salade","description":"La tarte du Nord : pâte brisée pur beurre maison garnie de fondue de poireaux, d'œufs, de crème et de lamelles de maroilles fondant. Avec une salade verte.","emoji":"🥧","category":"plat","mealTypes":["dejeuner","diner"],"cuisine":"francaise","prepTime":30,"cookTime":55,"restTime":30,"difficulty":"intermediaire","servings":3,"ingredients":[{"id":"farine","qty":180,"unit":"g"},{"id":"beurre","qty":110,"unit":"g","note":"dont 90 g froid pour la pâte"},{"id":"eau","qty":40,"unit":"ml","note":"glacée"},{"id":"poireau","qty":4,"unit":"piece","note":"émincés"},{"id":"oeuf","qty":5,"unit":"piece"},{"id":"creme-fraiche","qty":100,"unit":"ml"},{"id":"reblochon","qty":180,"unit":"g","note":"maroilles, en lamelles"},{"id":"muscade","qty":1,"unit":"pincee"},{"id":"laitue","qty":150,"unit":"g"},{"id":"vinaigre-cidre","qty":1,"unit":"cas"},{"id":"sel","qty":1,"unit":"au-gout"},{"id":"poivre","qty":1,"unit":"au-gout"}],"steps":["Pâte : sablez la farine, une pincée de sel et 90 g de beurre froid en dés du bout des doigts. Ajoutez 1 œuf et l'eau glacée, rassemblez en boule sans pétrir. Filmez et réservez 30 min au frais.","Faites fondre les poireaux dans le reste du beurre à feu doux 20 min à couvert, en remuant de temps en temps : ils doivent être tendres et sans coloration. Salez et laissez tiédir.","Préchauffez le four à 190 °C. Abaissez la pâte à 3 mm, foncez un moule de 26 cm, piquez le fond et faites précuire 12 min à blanc (lestée de papier et de légumes secs).","Battez les 4 œufs restants avec la crème, la muscade, sel et poivre. Ajoutez les poireaux.","Versez sur le fond de tarte, répartissez les lamelles de maroilles et enfournez 30 à 35 min, jusqu'à ce que l'appareil soit pris et le dessus doré et bouillonnant.","Laissez reposer 5 min et servez avec la salade assaisonnée au vinaigre."],"tags":["four","familial","réconfortant","calorique","lunch box"],"seasons":["automne","hiver","printemps"],"technique":"four","flavors":["lacte","reconfortant"],"tips":"Se mange aussi tiède ou froide le lendemain, idéale en lunch box."}]`);export{e as default};